import{z as B,x as p,o as l,c as d,q as i,j as s,D as r,d as t,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"锁存与触发器","description":"","frontmatter":{"title":"锁存与触发器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/latch-flipflop.md","filePath":"cs/latch-flipflop.md","lastUpdated":1791063341000}'),D={name:"cs/latch-flipflop.md"};function A(F,a,h,f,m,c){const E=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=i('<h1 id="锁存与触发器" tabindex="-1">锁存与触发器 <a class="header-anchor" href="#锁存与触发器" aria-label="Permalink to &quot;锁存与触发器&quot;">​</a></h1><div class="epigraph"><p>组合网没有记忆；要让比特在时钟拍之间还在，必须用交叉耦合或边沿采样把状态关进回路里。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/pla-rom">PLA 与 ROM 作组合</a>把组合算术收到「三种比较」。本课不重接线旗标，也不从操作系统进程另起。缺口是：到现在所有块都是 \\(y=f(x)\\)。计数器、寄存器、后课 PC，需要 \\(y\\) 依赖<strong>过去</strong>。数字逻辑在这里进入时序：锁存与触发器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合反馈可以振荡或进入亚稳，不能当受控记忆。缺口是受控存储元件：电平敏感的 <strong>D 锁存</strong>在时钟高（或低）时透明、否则保持；边沿敏感的 <strong>D 触发器</strong>只在上升沿（或下降沿）把 D 送入 Q。后课同步设计默认触发器，避免透明造成的环路同时导通。</p><p>SRAM 单元也是交叉耦合，但是阵列课的对象；本课只钉 1 比特的锁存/FF。</p><h3 id="锁存不是触发器" tabindex="-1">锁存不是触发器 <a class="header-anchor" href="#锁存不是触发器" aria-label="Permalink to &quot;锁存不是触发器&quot;">​</a></h3><p>教科书与口语常把 flip-flop 与 latch 混用。本栏：latch 电平透明，FF 边沿。用两个锁存主从可以拼成 FF。把锁存当 FF 用在同一时钟上，保持时间与环路会一起坏。</p><p><span class="marginnote">术语翻译：电平敏感 = 时钟停在那个电平的整段时间里，输入都直接「穿透」到输出，像一扇一直开着的门；边沿敏感 = 只在时钟跳变的那一瞬间拍一张快照，之后输入怎么变都与输出无关。两句话的区别就是「门开着」与「快门按了一下」。</span></p><p><span class="marginnote">Harris 用时序图区分透明窗与边沿。本课不把 JK、T 触发器当主干：它们可由 D 与组合构成。异步置位清零当端口承认，不展开异步状态机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SR 交叉耦合：禁止 \\(S=R=1\\) 的那种。D 锁存：时钟选通，透明时 \\(Q=D\\)。主从：前级锁存在时钟一半透明，后级在另一半，整体边沿。触发器输出 Q 在周期内除边沿外保持。</p>',12)),(l(),s(n,null,{default:r(()=>[o(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMB%5B%22%E7%BB%84%E5%90%88%20y%3Df(x)%22%5D%20--%3E%20LAT%5B%22D%20%E9%94%81%E5%AD%98%EF%BC%9A%E9%80%8F%E6%98%8E%E7%AA%97%22%5D%0A%20%20LAT%20--%3E%20FF%5B%22%E8%BE%B9%E6%B2%BF%20D%20%E8%A7%A6%E5%8F%91%E5%99%A8%22%5D%0A%20%20FF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%BA%E7%AB%8B%E4%B8%8E%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了 FF，才能切出「周期」：周期内组合计算，边沿更新状态。后课寄存器是并排 FF；FSM 的现态是一组 FF。时钟尚未多域，本课假设单时钟理想边沿。亚稳态：若 D 在边沿附近变，Q 可能长时间不合法——量化是下一课建立保持。复位可以同步接到 D 的 MUX，也可以异步进 FF 端口；主干默认同步复位，避免与时钟竞争。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：主从两级像地铁进站的两道闸机门——外门（主锁存）开的时候内门（从锁存）关着；外门关上的同一瞬间内门才放行。乘客（数据）恰好一个节拍通过一个，既不会一路直穿，也不会被夹在中间。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为 D 在边沿附近变化，最多是采到旧值或新值二者之一。实际上 FF 可能进入亚稳态：Q 停在 0 与 1 之间的中间电平来回振荡，过一段随机长的时间才掉向一边。跨时钟域信号若不做同步器，就是在赌亚稳态的恢复时间。")],-1)),(l(),s(n,null,{default:r(()=>[o(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22CLK%3D0%22%5D%20--%3E%20M1%5B%22%E4%B8%BB%E9%94%81%E5%AD%98%E9%80%8F%E6%98%8E%3A%20%E8%B7%9F%E9%9A%8F%20D%22%5D%0A%20%20L0%20--%3E%20S1%5B%22%E4%BB%8E%E9%94%81%E5%AD%98%E5%85%B3%E9%97%AD%3A%20Q%20%E4%BF%9D%E6%8C%81%E6%97%A7%E5%80%BC%22%5D%0A%20%20E%5B%22CLK%20%E4%B8%8A%E5%8D%87%E6%B2%BF%E7%9E%AC%E9%97%B4%22%5D%20--%3E%20FZ%5B%22%E4%B8%BB%E9%94%81%E5%AD%98%E5%86%BB%E7%BB%93%E5%BD%93%E6%97%B6%E7%9A%84%20D%22%5D%0A%20%20L1%5B%22CLK%3D1%22%5D%20--%3E%20S2%5B%22%E4%BB%8E%E9%94%81%E5%AD%98%E9%80%8F%E6%98%8E%3A%20Q%20%E8%BE%93%E5%87%BA%E5%86%BB%E7%BB%93%E5%80%BC%22%5D%0A%20%20L1%20--%3E%20M2%5B%22%E4%B8%BB%E9%94%81%E5%AD%98%E5%85%B3%E9%97%AD%3A%20D%20%E5%86%8D%E5%8F%98%E4%B9%9F%E8%BF%9B%E4%B8%8D%E6%9D%A5%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>这张图回答的问题：为什么两个「电平敏感」的锁存能拼出一个「边沿敏感」的触发器。秘诀是两级错相——任意时刻两级必有一级关闭，D 到 Q 的通路只在上升沿这一瞬接通，这正是后课同步设计敢把所有状态放在 FF 里的原因。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PLL、不把 DRAM 电容当 FF。不引入多时钟。组合逻辑险象若打在锁存透明窗里会被放行；FF 只采样边沿附近。</p><p>后课默认：同步状态存在边沿 D 触发器里；锁存仅在明确的透明协议里使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>记忆需要锁存或触发器；组合反馈不是受控状态。</li><li>锁存电平透明；FF 边沿采样。</li><li>时序约束（建立/保持）下一课才写成不等式。</li><li>主干默认同步复位，避免异步端口与时钟竞争。</li><li>出处：Harris and Harris。</li></ul>',6))])}const T=B(D,[["render",A]]);export{_ as __pageData,T as default};
